package com.pranit.productsupport.bff.config;
import javax.crypto.SecretKey;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.util.List;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.jwt.JwtDecoder;import org.springframework.security.oauth2.jwt.NimbusJwtDecoder;import org.springframework.security.oauth2.jwt.JwtValidators;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig {@Bean JwtDecoder jwtDecoder(@Value("${app.security.jwt-secret}") String value){byte[] bytes=value.getBytes(StandardCharsets.UTF_8);if(bytes.length<32)throw new IllegalStateException("JWT_SECRET must be at least 32 bytes");SecretKey key=new SecretKeySpec(bytes,"HmacSHA256");NimbusJwtDecoder d=NimbusJwtDecoder.withSecretKey(key).macAlgorithm(MacAlgorithm.HS256).build();d.setJwtValidator(JwtValidators.createDefaultWithIssuer("product-support-platform"));return d;}@Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{http.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/**","/api/v1/webhooks/razorpay","/actuator/health/**","/actuator/info").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter())));return http.build();}@Bean JwtAuthenticationConverter converter(){JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(jwt->{List<String> roles=jwt.getClaimAsStringList("roles");return roles==null?List.of():roles.stream().map(SimpleGrantedAuthority::new).toList();});return c;}}
